#!/usr/bin/env python3
"""ROM-free purpose classification plus unchanged microcode/state/bus regression."""
from pathlib import Path
import argparse,hashlib,json,os,signal,subprocess,sys,time,re
ROOT=Path(__file__).resolve().parents[1]
def require(v,why):
 if not v:raise RuntimeError(why)
def identity(p):return {'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def save(p,v):
 with p.open('x') as f:json.dump(v,f,indent=2);f.write('\n')
def bounded(command,out,label):
 start=time.monotonic();process=None
 try:
  with (out/(label+'.stdout')).open('xb') as so,(out/(label+'.stderr')).open('xb') as se:
   process=subprocess.Popen(command,cwd=ROOT,stdout=so,stderr=se,start_new_session=True)
   while process.poll() is None:
    require(time.monotonic()-start<180,'180s group watchdog');require(sum(p.stat().st_size for p in out.rglob('*') if p.is_file())<128*1024*1024,'128MiB output cap');require(sum(p.stat().st_size for p in out.glob('*.std*'))<16*1024*1024,'16MiB log cap');time.sleep(.1)
  require(process.returncode==0,'first '+label+' failure: '+str(process.returncode));return time.monotonic()-start
 finally:
  if process is not None and process.poll() is None:
   os.killpg(process.pid,signal.SIGTERM)
   try:process.wait(timeout=3)
   except subprocess.TimeoutExpired:os.killpg(process.pid,signal.SIGKILL);process.wait(timeout=3)
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',required=True,type=Path);p.add_argument('--reference-dir',required=True,type=Path);p.add_argument('--baseline-generator',required=True,type=Path,help='unchanged accepted generator, SHA aef2ea3d...');a=p.parse_args();OLD=a.baseline_generator.resolve();out=a.output.resolve();require(out.is_relative_to(ROOT/'build'),'exclusive ignored output');out.mkdir(parents=True,exist_ok=False);started=time.monotonic()
 sources=[Path(__file__).resolve(),ROOT/'tests/test_m68k_reference_access_roles.cpp',ROOT/'tests/test_m68k_timing_reference.py',ROOT/'tests/m68k_reference_access_roles.py',OLD,*[a.reference_dir/name for name in ['m68000.cpp','m68000.h','m68000.lst','m68000gen.py']]];before={str(p):identity(p) for p in sources};save(out/'inputs-before.json',before)
 commands=[]
 try:
  require(identity(OLD)['sha256']=='aef2ea3d95248703b5241b25feac70c0205abfc6d32e72218431ec151537254e','unchanged frozen original generator')
  ops=out/'public-opcodes.txt';ops.write_text('103a\n2039\n203a\n203c\n303a\n337b\n4e71\n6000\n')
  for label,script,roles in [('old',OLD,False),('plain',ROOT/'tests/test_m68k_timing_reference.py',False),('tagged',ROOT/'tests/test_m68k_timing_reference.py',True)]:
   command=[sys.executable,str(script),'--reference-dir',str(a.reference_dir),'--output',str(out/label),'--board-opcodes',str(ops)]
   # The old generator only admits output under its own ignored build root.
   if label=='old':
    # Avoid changing that frozen worktree at all: copy its public script into
    # this exclusive output. ROOT becomes out.parent, which remains ignored.
    script_copy=out/'original-generator/tests/test_m68k_timing_reference.py';script_copy.parent.mkdir(parents=True);script_copy.write_bytes(OLD.read_bytes());command[1]=str(script_copy);command[command.index('--output')+1]=str(out/'original-generator/build/old')
   if roles:command.append('--board-access-roles')
   commands.append(command);bounded(command,out,label)
  old=(out/'original-generator/build/old/m68000-board-reference.h').read_bytes();plain=(out/'plain/m68000-board-reference.h').read_bytes();tagged=(out/'tagged/m68000-board-reference.h').read_text()
  require(old==plain,'default board generated bytes unchanged')
  stripped=re.sub(r"^[ \t]*observer_access_role = '[podi]';\n",'',tagged,flags=re.M).replace("char observer_access_role='?';\n ",'').replace("kind=='p'?observer_access_role:kind",'kind')
  require(stripped.encode()==plain,'purpose tags stripped reconstruct identical generated CPU code/scaffold')
  binary=out/'test-m68k-reference-access-roles';command=['/usr/bin/c++','-std=c++20','-O1','-g','-fno-fast-math','-ffp-contract=off','-I'+str(out),str(ROOT/'tests/test_m68k_reference_access_roles.cpp'),'-o',str(binary)];commands.append(command);bounded(command,out,'build');command=[str(binary)];commands.append(command);bounded(command,out,'run')
  require(before=={str(p):identity(p) for p in sources},'all sources unchanged');save(out/'commands.json',commands);save(out/'result.json',{'status':'PASS','seconds':time.monotonic()-started,'inputs':before,'artifacts':{str(p.relative_to(out)):identity(p) for p in out.rglob('*') if p.is_file()},'scope':'ROM-free purpose observer only; no actual sound tape execution or hardware bus-phase claim'});print('PASS:',out/'result.json')
 except BaseException as error:save(out/'commands.json',commands);save(out/'result.json',{'status':'FAIL','error':str(error),'seconds':time.monotonic()-started,'retry':'none'});raise
if __name__=='__main__':main()
